export const PECAS_PRAIA = Object.keys(PECAS)                        ;

export function pintarPecaPraia(pintar             , nome           , x        , y        )       {
  const linhas = PECAS[nome];
  linhas.forEach((linha, j) => {
    // Junta somente pixels de mesma cor, sem encostar nas áreas transparentes.
    for (let i = 0; i < linha.length;) {
      const indice = linha[i];
      let fim = i + 1;
      while (linha[fim] === indice) fim++;
      const cor = PALETA[indice];
      if (cor) pintar(cor, x + i, y + j, fim - i, 1);
      i = fim;
    }
  });
}
